    RecurringPriceAcknowledgement = apps.get_model("finance", "RecurringPriceAcknowledgement")
    rows = (
        RecurringSeries.objects.filter(acknowledged_amount_minor__isnull=False)
        .values_list("pk", "person_id", "acknowledged_amount_minor")
        .iterator()
    )
    RecurringPriceAcknowledgement.objects.bulk_create(
        [
            RecurringPriceAcknowledgement(series_id=series_id, person_id=person_id, amount_minor=amount_minor)
            for series_id, person_id, amount_minor in rows
        ],
        batch_size=500,
    )


